pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        // Restrict to admissible domain: amount > 0 so the Caller obtains a positive balance
        vm.assume(amount > 0);
        // Deploy the re-entrant attacker helper
        ReEntrantCaller caller = new ReEntrantCaller(c);
        vm.deal(address(caller), amount);
        // The attacker invokes Put, which will re-enter Put once via fallback, totalling 2 Put calls for the same msg.value
        caller.attack{value: amount}(unlockTime);
        // General rule: a call to Put must never increase the caller's stored balance by more than msg.value.
        // The bug breaks this because the reentrancy lock is removed, so the balance is incremented twice with the same msg.value.
        ( , uint256 balance) = c.Acc(address(caller));
        assertTrue(balance <= amount, "Balance exceeded msg.value due to reentrancy");
    }
}

contract ReEntrantCaller {
    C public target;
    uint256 public unlockTime;
    bool private attacking;
    constructor(C _target) { target = _target; }
    function attack(uint256 _unlockTime) external payable {
        unlockTime = _unlockTime;
        attacking = true;
        target.Put{value: msg.value}(_unlockTime);
        attacking = false;
    }
    fallback() external payable {
        if (attacking && msg.sender == address(target)) {
            attacking = false;
            target.Put{value: 0}(unlockTime);
        }
    }
}

