pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 _unlockTime, uint64 _fut, uint128 _amount) public {
        // admissible: _unlockTime must be in the future, amount >= MinSum (so we can later try Collect)
        vm.assume(_unlockTime > block.timestamp);
        vm.assume(_amount >= c.MinSum());
        uint256 fut = block.timestamp + uint256(_fut) + 1; // guaranteed future
        vm.assume(fut > block.timestamp);
        vm.assume(_unlockTime >= fut); // the provided unlockTime is at least as far as fut

        address caller = address(uint160(uint256(keccak256(abi.encode(_unlockTime, _fut, _amount)))));
        vm.deal(caller, _amount + 1 ether); // enough for Put and gas
        vm.startPrank(caller);
        c.Put{value: _amount}(_unlockTime);
        vm.stopPrank();

        // Warp to after the recorded unlockTime in the correct contract (_unlockTime)
        vm.warp(_unlockTime + 1);

        // Now try to Collect _amount. In the correct contract, unlockTime is _unlockTime, which has passed, so Collect should succeed.
        // In the mutant, unlockTime is block.timestamp at Put time, which is <= _unlockTime at Put, so after warp(_unlockTime+1),
        // unlockTime is still block.timestamp at Put (which is in the past), BUT the mutant's unlockTime is not the future _unlockTime;
        // actually the mutant sets unlockTime = block.timestamp at Put, which is now definitely in the past, so Collect should still succeed.
        // Wait — that means the mutant does NOT break the property that warp > unlockTime allows Collect.
        // The difference: the CORRECT contract has unlockTime = _unlockTime (future), so BEFORE _unlockTime, Collect must REVERT.
        // After _unlockTime, Collect succeeds. The MUTANT sets unlockTime = block.timestamp (which is now), so BEFORE the future _unlockTime,
        // Collect could SUCCEED earlier (since the mutant's unlockTime is now, not future).
        // So the rule: After a Put with future _unlockTime, if we warp to a time before _unlockTime, Collect must revert.
        // For the mutant, Collect will NOT revert because unlockTime is block.timestamp at Put (in the past), so it succeeds.

        // We'll check that before _unlockTime, Collect reverts.
        uint256 beforeFuture = _unlockTime - 1;
        vm.warp(beforeFuture);

        vm.prank(caller);
        try c.Collect(_amount) {
            // Collect succeeded – this is wrong for the reference, but the mutant does this, so we assert the opposite.
            // We want the reference to PASS (i.e., Collect reverts), so we assert false when it succeeds.
            assertTrue(false, "Collect should have reverted before unlockTime");
        } catch {
            // Collect reverted – this is correct for the reference, so we assert true.
            assertTrue(true);
        }
    }
}

