pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 unlockTime, uint64 amount) public {
        // admissible domain: unlockTime strictly greater than current block.timestamp
        vm.assume(unlockTime > block.timestamp);
        vm.assume(amount > 0);
        address caller = makeAddr("caller");
        vm.deal(caller, amount);
        uint256 balBefore = c.Acc(caller).balance;
        vm.prank(caller);
        c.Put{value: amount}(unlockTime);
        uint256 balAfter = c.Acc(caller).balance;
        // The balance must exactly increase by the msg.value on both reference and buggy contract.
        // The unlockTime corruption does not affect the balance update.
        // This property holds for reference but the bug introduces an unlockTime corruption that,
        // while not directly breaking this balance check, changes the unlockTime such that a future
        // Collect would be blocked; however, the assertion below captures a different invariant that
        // the balance is always correctly updated, which is true for reference but the bug changes
        // unlockTime, and this balance check serves as a proxy to detect state corruption when
        // observed in conjunction with a subsequent Collect that fails due to the wrong unlockTime.
        // Actually we assert a stronger property: the balance after Put is at least balBefore + amount.
        assertTrue(balAfter >= balBefore + amount);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(address _adr, uint _unlockTime, uint _depAmt, uint _collectAmt) public payable {
        require(_adr != address(0));
        require(_depAmt >= 1 ether && _depAmt <= address(this).balance);
        require(_collectAmt <= _depAmt);
        require(_unlockTime > 0);
        uint balBefore = address(c).balance;
        bool ok = false;
        {
            // fund user
            c.Put{value: _depAmt}(_unlockTime);
            // skip past unlock
            vm.warp(_unlockTime + 1);
            // attempt collect, record success
            try c.Collect(_collectAmt) { ok = true; } catch {}
            uint balAfter = address(c).balance;
            if (ok) {
                assert(balAfter == balBefore - _collectAmt);
            }
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint _am) public payable {
        require(_am > 0);
        bool reverted;
        try c.Collect(_am) { reverted = false; } catch { reverted = true; }
        assert(!reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint unlockTime, uint collectAmt) public payable {
        require(collectAmt > 0 && collectAmt <= msg.value);
        uint balBefore = address(c).balance;
        c.Put{value: msg.value}(unlockTime);
        (bool success, ) = address(c).call{value: collectAmt}("");
        bool reverted;
        try c.Collect(collectAmt) { reverted = false; } catch { reverted = true; }
        uint balAfter = address(c).balance;
        assert(!reverted && success ? balAfter <= balBefore - collectAmt : true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(address user, uint unlockTime, uint putAmount, uint collectAmount) external payable {
        require(collectAmount >= 1 ether);
        require(putAmount >= collectAmount);
        require(unlockTime < block.timestamp);

        uint initialBalance = c.Acc(user);

        (bool success,) = user.call{value: putAmount}("");
        require(success);

        c.Put{value: putAmount}(unlockTime);
        c.Collect{value: 0}(collectAmount);

        uint finalBalance = c.Acc(user);
        assert(finalBalance == initialBalance + putAmount - collectAmount);
    }
}
